) AS (
  VALUES 
    (524::BIGINT, 'Explica bastante bien y fácil, el porcentaje de tareas es prácticamente regalado y ayuda si ve que usted es centrado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '17c23c7a5505bdadcfc9a69a53d36ea5a4fa43a88407e61ea120d88c1555a949'::TEXT, ARRAY[605]::BIGINT[]),
    (524::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0490dfc8ff7937183292a0f29770bf00cccd9e62bb8f7a7d6fb5b64691e7f053'::TEXT, ARRAY[923]::BIGINT[]),
    (524::BIGINT, 'Excelente profesor, desarrolla muy bien los temas y explica la lógica detrás de los ejercicios para que hacerlos no se vuelva algo mecánico. Ayuda si ve que uno le pone bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'c904e8051236a79efb9e34a38eb51ee2939679ee909dbf135c3f39fa8358911f'::TEXT, ARRAY[563]::BIGINT[]),
    (524::BIGINT, 'El mejor profesor que he tenido en la universidad, excelente persona y profesor. Simplemente 20/10.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, '4b5dc2339fbf7716ef1e4c244943983fdcce66227cfa83077ec08b0c34d6824a'::TEXT, ARRAY[563]::BIGINT[]),
    (524::BIGINT, 'VIRTUAL. Las clases son muy largas, 1 hora 30 de clase y deja al menos 2 videos extra de 1-2 horas cada uno. No acepta ningún atraso. Deja bastantes tareas pero ayudan para los examenes.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '05c1807cd961becf9d14a725fa9ee9db4347274fc1269818c7062933fbe089b7'::TEXT, ARRAY[634]::BIGINT[]),
    (524::BIGINT, 'Explica muy bien la materia deja bastantes tareas que te ayuda a comprender los temas. La catedra seria lo único que le podría bajar la nota. No acepta tareas con tardía.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'b5ecfea652e3b0eb321f47c9f78cacb55ee5a6616dd3e015df206546c9852f27'::TEXT, ARRAY[563]::BIGINT[]),
    (524::BIGINT, 'Buen profe, deja vídeos de apoyo, pero explica bastante rápido, lo que mata es la cátedra de discreta'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'de13beb6c10f19fc0cfc3d6eb5e6c1f16a3ca95e3a53e0f4c9924dca2fe20d97'::TEXT, ARRAY[1018]::BIGINT[]),
    (524::BIGINT, 'Hay que seguirle el ritmo en las explicaciones, excelente profe. No intenten atrasar fechas ni justificar una tardía de tarea porque no la aceptara. Una clase por semana. Deja muchos videos grabados y generalmente son largos, acomódense para verlos, son muy útiles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '7fc4455cbe744b2d00b5471bf91af1d19d91cc3d8d8ccfeca4111c75ab358ce8'::TEXT, ARRAY[634]::BIGINT[]),
    (524::BIGINT, 'El profe es muy bueno, es puntual con las dudas que tenga. Pero deja muchos videos largos como de 2 horas, videos de otros semestres y explica muy rápido. Lo prepara bien para los examenes.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '93a0be101d243833ba5d3cef19ba789bcd043da52d11dcda7f8f64c9cd02e81c'::TEXT, ARRAY[634]::BIGINT[]),
    (524::BIGINT, 'El profe es super carga, es preocupado por los estudiantes, deja tareas que funcionan de práctica y es un porcentaje que ayuda y es fácil de ganar Las clases son un poco largas y aveces casi no se le entiende la letra, pero creo que fue por la modalidad virtual. El profe le pone muchas ganas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'f14a667319d1936034d92a4bd90a433c0d3261ad3864329a7ace52043b2f3248'::TEXT, ARRAY[605]::BIGINT[]),
    (524::BIGINT, '[VIRTUAL] El profe como tal es bueno, pero no el mejor. Resulta difícil seguirle el paso porque va muy rápido y tiene ya definidos los ejercicios de la clase entonces a veces no hace los que los estudiantes le proponen Es muy ordenado pero son muchos los videos que sube y a veces es tedioso verlos'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'f8c7c20cb0a8007b205c10de0cf1f86002356919d840418d782f623710922999'::TEXT, ARRAY[605]::BIGINT[]),
    (524::BIGINT, 'AL INICIO MUY CLARO DESPUES SE ENREDA MUCHO Y NO ME PARECE TAN BUENO COMO DICEN'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '62182c875103de44eb37391d91a1c587bbf405c771757ecba08386358a83bf28'::TEXT, ARRAY[923]::BIGINT[]),
    (524::BIGINT, 'Posiblemente el mejor profe de la escuela de mate que haya tenido. Se entrega totalmente al curso incluso en horas o dias en los que no debería dejando ejemplos extra. Totalemente recomendado. Al ser virtual no importa la sede en que dé, si es de la central y se quedó sin campo, meta 1000% con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'dc4436144182c0f4a0a68c44e9197a4680b22150bd377f2fa34d0276fcd72e5e'::TEXT, ARRAY[923]::BIGINT[]),
    (524::BIGINT, 'Excelente profe, dedica totalmente su tiempo y hasta de más. Da bastante tarea y quices para la retroalimentación, explica muy bien. Lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'b08ffe6873fd67a5dd3ab52e065e48ed4029eaf9c9eec86f862ef9a2b9085188'::TEXT, ARRAY[923]::BIGINT[]),
    (524::BIGINT, 'Es uno de los mejores profesores del Centro Académico de Limón de la escuela de matemáticas. Procura que los estudiantes aprendan, si usted tiene alguna duda él no tiene problema con ayudarlo las veces que sean. Prepara muy bien para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'bdf00ad8690dbe45cf10c052772ac4331a773e151618e466ba4c807ad20793cb'::TEXT, ARRAY[605]::BIGINT[]),
    (524::BIGINT, 'Es un excelente profesor, lo recomiendo mucho. Sin embargo durante este semestre virtual, cambio un poco la modalidad en la que enseñaba. Ahora deja ejercicios al final de clase para que cada estudiante lo trabaje a conciencia. Da mucha materia que es esencial para los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0609da94b65dd03becaa92bbfabde3e00c5f7e3e4a664e92f9d5194b0d20ca0e'::TEXT, ARRAY[634]::BIGINT[]),
    (524::BIGINT, 'Excelente profesor, de lo mejor que puede tener el Centro Académico de Limón. Es claro a la hora de explicar, se preocupa por que los estudiantes entiendan, brinda material de apoyo con prácticas electivas y se preocupa por recordar los errores comunes para que no los comentan en los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e24175bb34c1ff579a55755b75128b71d8624ff98c34e11089b73fbfd915005e'::TEXT, ARRAY[563]::BIGINT[]),
    (524::BIGINT, 'Es un excelente profersor, deja bastantes tareas, da muy buena retroalimentación para los examenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '86c381c4c3b6b83f7766d568adbe45857a395f739394c0c518e278d34035a6b4'::TEXT, ARRAY[605]::BIGINT[]),
    (524::BIGINT, 'Muy buen profesor y siempre busca una manera para que el estudiante tenga posibilidad de pasar'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'b8ebc5b841f9f70f7ceb1c0113f594c5a59497aefdcf4311b0e32e5e7790c0cb'::TEXT, ARRAY[1049]::BIGINT[]),
    (524::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'db11a6f0c1ae3771353658b04ee91e260a009c0c9816b0982e92ec660d83066e'::TEXT, ARRAY[1018]::BIGINT[]),
    (524::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5fd300545c24bb1f1b407b383f00f0bd97a712b6c3749123c803015e2677e8fb'::TEXT, ARRAY[923]::BIGINT[]),
    (524::BIGINT, 'Es un gran profesor, se preocupa por los estudiantes y su aprendizaje y siempre nos enseña cada lección nunca rendirse y esforzarse.... Nació para enseñar'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2016-12-13T00:00:00+00:00'::TIMESTAMPTZ, '1f165a7fd8b26a15593d1fc901e2252224e1d5c69f4fcad90fff8a0df30db074'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
